import Foundation

/// Geometry of the anatomical body map, in a 200 × 410 design space, plus hit-testing.
/// Kept here (not in the view) so taps can be resolved and tested without SwiftUI.
/// Shapes come from `BodyMapGeometry.swift`, generated by ios/Tools/bodymap/generate.py (#110).
public enum BodyMapLayout {
    public enum Side: String, CaseIterable, Sendable, Identifiable {
        case front, back
        public var id: String { rawValue }
    }

    /// Body figure drawn on maps (#110). Display only: separate from the optional sex / gender fields.
    public enum Figure: String, Codable, CaseIterable, Sendable, Identifiable {
        case male, female
        public var id: String { rawValue }
        public var label: String { self == .male ? "M" : "F" }
    }

    public static let width: Double = 200
    public static let height: Double = 410

    public struct Point: Sendable, Equatable {
        public let x, y: Double
    }

    /// Raw generated data: flat x, y pairs.
    struct Sheet: Sendable {
        let outline: [[Double]]
        let muscles: [(Muscle, [Double])]
        let details: [[Double]]
    }

    /// One drawn muscle polygon (the view smooths it).
    public struct Shape: Sendable, Equatable {
        public let muscle: Muscle
        public let points: [Point]

        /// Area centroid.
        public var midX: Double { centroid.x }
        public var midY: Double { centroid.y }

        public var centroid: Point {
            var a = 0.0, cx = 0.0, cy = 0.0
            for i in points.indices {
                let p = points[i], q = points[(i + 1) % points.count]
                let c = p.x * q.y - q.x * p.y
                a += c
                cx += (p.x + q.x) * c
                cy += (p.y + q.y) * c
            }
            guard abs(a) > 1e-9 else { return points.first ?? Point(x: 0, y: 0) }
            return Point(x: cx / (3 * a), y: cy / (3 * a))
        }

        /// Even-odd point-in-polygon.
        public func contains(x: Double, y: Double) -> Bool {
            var inside = false
            var j = points.count - 1
            for i in points.indices {
                let pi = points[i], pj = points[j]
                if (pi.y > y) != (pj.y > y), x < (pj.x - pi.x) * (y - pi.y) / (pj.y - pi.y) + pi.x {
                    inside.toggle()
                }
                j = i
            }
            return inside
        }
    }

    private static func points(_ flat: [Double]) -> [Point] {
        stride(from: 0, to: flat.count - 1, by: 2).map { Point(x: flat[$0], y: flat[$0 + 1]) }
    }

    /// Every muscle polygon drawn for a side, mirrored twins included, in draw order (later on top).
    public static func shapes(_ side: Side, figure: Figure = .male) -> [Shape] {
        sheet(figure, side).muscles.map { Shape(muscle: $0.0, points: points($0.1)) }
    }

    /// Silhouette polygons (head, body), back to front.
    public static func outline(_ side: Side, figure: Figure = .male) -> [[Point]] {
        sheet(figure, side).outline.map(points)
    }

    /// Faint anatomical detail lines (open polylines): ab segments, spine, kneecaps.
    public static func details(_ side: Side, figure: Figure = .male) -> [[Point]] {
        sheet(figure, side).details.map(points)
    }

    /// Muscles shown on a side, in draw order, without duplicates.
    public static func muscles(_ side: Side) -> [Muscle] {
        var seen = Set<Muscle>()
        return shapes(side).map(\.muscle).filter { seen.insert($0).inserted }
    }

    /// Muscle under a point in design space; where polygons overlap, the top-most (last drawn) wins.
    /// Nil outside every muscle.
    public static func muscle(at x: Double, _ y: Double, side: Side, figure: Figure = .male) -> Muscle? {
        shapes(side, figure: figure).last { $0.contains(x: x, y: y) }?.muscle
    }
}
